DATA.units = [
/* ============ A1 ============ */
{id:'a1u1',lv:'A1',title:'Chào hỏi & động từ to be',goal:'Giới thiệu bản thân và hỏi thông tin cá nhân.',
 vocab:[['name','/neɪm/','tên','My name is Linh.'],['country','/ˈkʌntri/','quốc gia','My country is Vietnam.'],['job','/dʒɑːb/','nghề nghiệp','What is your job?'],['student','/ˈstuːdnt/','sinh viên','She is a student.'],['teacher','/ˈtiːtʃɚ/','giáo viên','He is a teacher.'],['friend','/frend/','bạn bè','Anna is my friend.'],['family','/ˈfæməli/','gia đình','I love my family.'],['phone number','/ˈfoʊn ˌnʌmbɚ/','số điện thoại','What’s your phone number?']],
 grammar:{body:'<p><b>to be</b>: I <b>am</b> · you/we/they <b>are</b> · he/she/it <b>is</b>.</p><ul><li>Phủ định: I am <b>not</b> / he <b>isn’t</b> / they <b>aren’t</b>.</li><li>Câu hỏi: <b>Are</b> you a student? – Yes, I am. / No, I’m not.</li><li>Rút gọn: I’m, you’re, he’s, we’re.</li></ul>',
  quiz:[{q:'I ___ a student.',o:['am','is','are'],a:0,e:'I đi với am.'},{q:'She ___ from Vietnam.',o:['am','is','are'],a:1,e:'she → is.'},{q:'___ you a teacher?',o:['Is','Am','Are'],a:2,e:'you → Are.'},{q:'They ___ not at home.',o:['is','are','am'],a:1,e:'they → are.'}]},
 listen:{dialog:[['A','Hello! What’s your name?','Xin chào! Bạn tên gì?'],['B','Hi, I’m Lan. What’s your name?','Chào, mình là Lan. Còn bạn?'],['A','I’m Tom. Where are you from?','Mình là Tom. Bạn đến từ đâu?'],['B','I’m from Vietnam. Are you from the USA?','Mình đến từ Việt Nam. Bạn đến từ Mỹ à?'],['A','No, I’m not. I’m from Canada.','Không. Mình đến từ Canada.']],
  qs:[{q:'What is the man’s name?',o:['Tom','Lan','Mark'],a:0,e:'“I’m Tom.”'},{q:'Where is Tom from?',o:['The USA','Canada','Vietnam'],a:1,e:'“I’m from Canada.”'}]},
 read:{text:'My name is Anna. I am twenty-five years old. I am from Canada. I am a nurse. I live in Toronto with my sister. Her name is Emma. She is a student.',
  qs:[{q:'How old is Anna?',o:['20','25','30'],a:1,e:'“twenty-five”.'},{q:'What is Anna’s job?',o:['Teacher','Student','Nurse'],a:2,e:'“I am a nurse.”'},{q:'Who is Emma?',o:['Anna’s sister','Anna’s friend','Anna’s mother'],a:0,e:'“my sister. Her name is Emma.”'}]},
 speak:{shadow:['Hello, my name is Linh. Nice to meet you.','I am from Vietnam. I am an accountant.'],prompt:'Giới thiệu bản thân trong 4 câu: tên, quê, nghề, gia đình.'},
 write:{prompt:'Write 5 sentences about yourself (name, age, country, job, family).',min:30,model:'My name is Linh. I am 28 years old. I am from Da Nang. I am an accountant. I live with my family in Ho Chi Minh City.'}},

{id:'a1u2',lv:'A1',title:'Thì hiện tại đơn – thói quen hằng ngày',goal:'Nói về thói quen và lịch sinh hoạt.',
 vocab:[['wake up','/weɪk ʌp/','thức dậy','I wake up at six.'],['breakfast','/ˈbrekfəst/','bữa sáng','I have breakfast at seven.'],['work','/wɝːk/','làm việc','She works in a bank.'],['lunch','/lʌntʃ/','bữa trưa','We eat lunch at noon.'],['bus','/bʌs/','xe buýt','He goes by bus.'],['evening','/ˈiːvnɪŋ/','buổi tối','In the evening I read.'],['sleep','/sliːp/','ngủ','I sleep at eleven.'],['weekend','/ˈwiːkend/','cuối tuần','I relax at the weekend.']],
 grammar:{body:'<p><b>Present simple</b>: thói quen, sự thật. I/you/we/they + V · he/she/it + V<b>-s/-es</b>.</p><ul><li>Phủ định: I <b>don’t</b> work · she <b>doesn’t</b> work.</li><li>Câu hỏi: <b>Do</b> you work? · <b>Does</b> she work?</li><li>Trạng từ tần suất: always, usually, often, sometimes, never (đứng trước động từ thường).</li></ul>',
  quiz:[{q:'He ___ to work by bus.',o:['go','goes','going'],a:1,e:'he + V-es.'},{q:'I ___ TV in the morning.',o:["don't watch","doesn't watch","not watch"],a:0,e:'I → don’t + V.'},{q:'___ she like coffee?',o:['Do','Does','Is'],a:1,e:'she → Does.'},{q:'We usually ___ dinner at seven.',o:['has','have','having'],a:1,e:'we + V nguyên mẫu.'}]},
 listen:{dialog:[['A','What time do you wake up?','Bạn thức dậy lúc mấy giờ?'],['B','I wake up at six. Then I have breakfast.','Mình dậy lúc sáu giờ. Rồi ăn sáng.'],['A','Do you go to work by bus?','Bạn đi làm bằng xe buýt à?'],['B','No, I go by bike. It takes twenty minutes.','Không, mình đi xe đạp. Mất hai mươi phút.'],['A','And what do you do in the evening?','Còn buổi tối bạn làm gì?'],['B','I cook dinner and watch TV.','Mình nấu bữa tối và xem TV.']],
  qs:[{q:'What time does B wake up?',o:['At five','At six','At seven'],a:1,e:'“I wake up at six.”'},{q:'How does B go to work?',o:['By bus','By bike','On foot'],a:1,e:'“I go by bike.”'}]},
 read:{text:'Tom is a bank clerk. He gets up at 6:30 and has a coffee. He goes to work by train. He works from nine to five. He never eats lunch at his desk. In the evening he plays football with friends. At the weekend he visits his parents.',
  qs:[{q:'How does Tom go to work?',o:['By train','By bus','By car'],a:0,e:'“by train”.'},{q:'What does Tom do in the evening?',o:['Cooks dinner','Plays football','Watches TV'],a:1,e:'“plays football with friends”.'},{q:'When does Tom visit his parents?',o:['On Monday','In the morning','At the weekend'],a:2,e:'“At the weekend”.'}]},
 speak:{shadow:['I usually wake up at six and have breakfast at seven.','She doesn’t work on Sundays.'],prompt:'Nói về một ngày bình thường của bạn (ít nhất 5 câu).'},
 write:{prompt:'Describe your daily routine in 6 sentences. Use usually, always, sometimes.',min:40,model:'I usually wake up at six. I have breakfast at seven and go to work by motorbike. I always start work at eight. I sometimes have lunch with my colleagues. In the evening I cook dinner and watch TV. I never go to bed after eleven.'}},

{id:'a1u3',lv:'A1',title:'There is / There are & giới từ chỉ nơi chốn',goal:'Mô tả nhà cửa và vị trí đồ vật.',
 vocab:[['kitchen','/ˈkɪtʃən/','nhà bếp','The kitchen is small.'],['bedroom','/ˈbedruːm/','phòng ngủ','There are two bedrooms.'],['bathroom','/ˈbæθruːm/','phòng tắm','The bathroom is next to the bedroom.'],['table','/ˈteɪbl/','cái bàn','The keys are on the table.'],['chair','/tʃer/','cái ghế','There is a chair by the window.'],['window','/ˈwɪndoʊ/','cửa sổ','Open the window, please.'],['next to','/ˈnekst tuː/','bên cạnh','The bank is next to the school.'],['between','/bɪˈtwiːn/','ở giữa','The shop is between two banks.']],
 grammar:{body:'<p><b>There is</b> + danh từ số ít / không đếm được · <b>There are</b> + danh từ số nhiều.</p><ul><li>Phủ định: There <b>isn’t</b> a sofa · There <b>aren’t</b> any chairs.</li><li>Câu hỏi: <b>Is there</b> a bank near here? – Yes, there is.</li><li>Giới từ: <b>in, on, under, next to, between, in front of, behind</b>.</li></ul>',
  quiz:[{q:'There ___ a bank near my house.',o:['is','are','am'],a:0,e:'a bank – số ít → is.'},{q:'There ___ three chairs in the room.',o:['is','are','be'],a:1,e:'three chairs – số nhiều → are.'},{q:'The cat is ___ the table. (bên dưới)',o:['on','under','between'],a:1,e:'under = bên dưới.'},{q:'___ there any milk?',o:['Is','Are','Do'],a:0,e:'milk không đếm được → Is there.'}]},
 listen:{dialog:[['A','Is there a supermarket near here?','Gần đây có siêu thị không?'],['B','Yes, there is. It’s next to the post office.','Có. Nó nằm cạnh bưu điện.'],['A','Where’s the post office?','Bưu điện ở đâu?'],['B','It’s between the bank and the cafe.','Nó nằm giữa ngân hàng và quán cà phê.'],['A','Thank you!','Cảm ơn bạn!']],
  qs:[{q:'What is next to the post office?',o:['A bank','A supermarket','A school'],a:1,e:'“supermarket … next to the post office”.'},{q:'Where is the post office?',o:['Between the bank and the cafe','Behind the bank','Next to the school'],a:0,e:'“between the bank and the cafe”.'}]},
 read:{text:'I live in a small flat. There is one bedroom, a bathroom and a kitchen. In the living room there is a sofa and a table. There are two windows and a TV. My desk is in front of the window. There are some books on the desk. I like my flat because it is quiet.',
  qs:[{q:'How many bedrooms are there?',o:['One','Two','Three'],a:0,e:'“one bedroom”.'},{q:'Where is the desk?',o:['Behind the sofa','In front of the window','Next to the TV'],a:1,e:'“in front of the window”.'},{q:'Why does the writer like the flat?',o:['It is big','It is cheap','It is quiet'],a:2,e:'“it is quiet”.'}]},
 speak:{shadow:['There is a sofa and a table in the living room.','The bank is next to the post office.'],prompt:'Mô tả phòng của bạn: có những gì và ở đâu.'},
 write:{prompt:'Describe your bedroom or living room. Use there is / there are and prepositions.',min:40,model:'There is a bed in my bedroom. The bed is next to the window. There is a small desk in front of the bed. There are some books on the desk and a lamp between the books. There are two pictures on the wall.'}},

{id:'a1u4',lv:'A1',title:'Can / can’t & câu mệnh lệnh',goal:'Nói về khả năng và đưa ra chỉ dẫn.',
 vocab:[['swim','/swɪm/','bơi','I can swim.'],['cook','/kʊk/','nấu ăn','She can cook well.'],['drive','/draɪv/','lái xe','He can’t drive.'],['sing','/sɪŋ/','hát','Can you sing?'],['speak','/spiːk/','nói','I can speak English.'],['open','/ˈoʊpən/','mở','Open the door, please.'],['close','/kloʊz/','đóng','Close the window.'],['help','/help/','giúp','Can you help me?']],
 grammar:{body:'<p><b>can</b> + V nguyên mẫu (không đổi theo ngôi): khả năng, xin phép, nhờ vả.</p><ul><li>Phủ định: I <b>can’t</b> swim.</li><li>Câu hỏi: <b>Can</b> you help me? – Yes, I can.</li><li><b>Imperative</b>: V nguyên mẫu. Open the door. · <b>Don’t</b> be late.</li></ul>',
  quiz:[{q:'She ___ speak three languages.',o:['can','cans','is can'],a:0,e:'can không thêm -s.'},{q:'I ___ drive a car.',o:["can't",'not can','no can'],a:0,e:'can’t = cannot.'},{q:'___ you help me, please?',o:['Do','Can','Are'],a:1,e:'Can you… = nhờ vả lịch sự.'},{q:'___ be late for class!',o:["Not",'No',"Don't"],a:2,e:'Phủ định mệnh lệnh: Don’t + V.'}]},
 listen:{dialog:[['A','Can you swim?','Bạn biết bơi không?'],['B','Yes, I can. I swim every weekend.','Có. Cuối tuần nào mình cũng bơi.'],['A','Can you cook?','Bạn nấu ăn được không?'],['B','No, I can’t. But I can make good coffee.','Không. Nhưng mình pha cà phê ngon.'],['A','Great! Can you make one for me?','Tuyệt! Pha cho mình một ly được không?']],
  qs:[{q:'Can B swim?',o:['Yes','No'],a:0,e:'“Yes, I can.”'},{q:'What can B make?',o:['Dinner','Coffee','Tea'],a:1,e:'“I can make good coffee.”'}]},
 read:{text:'Welcome to our English club! You can borrow books here, but you can’t take them home for more than a week. You can use the computers for free. Please don’t eat in the library. You can ask the teacher if you need help. Please turn off your phone.',
  qs:[{q:'How long can you keep a book?',o:['One day','One week','One month'],a:1,e:'“more than a week” không được.'},{q:'What can’t you do in the library?',o:['Use computers','Ask the teacher','Eat'],a:2,e:'“don’t eat”.'},{q:'What should you do with your phone?',o:['Turn it off','Give it to the teacher','Use it'],a:0,e:'“Please turn off your phone.”'}]},
 speak:{shadow:['I can speak English, but I can’t speak French.','Can you help me, please?'],prompt:'Nói về 5 việc bạn có thể và không thể làm.'},
 write:{prompt:'Write about what you can and can’t do (6 sentences).',min:40,model:'I can cook Vietnamese food. I can speak a little English. I can ride a motorbike, but I can’t drive a car. I can’t swim very well. I can play the guitar. I can’t sing.'}},

{id:'a1u5',lv:'A1',title:'Hiện tại tiếp diễn & mua sắm',goal:'Nói về việc đang làm và mua sắm cơ bản.',
 vocab:[['buy','/baɪ/','mua','I’m buying bread.'],['shop','/ʃɑːp/','cửa hàng','This shop is open.'],['price','/praɪs/','giá','What’s the price?'],['cheap','/tʃiːp/','rẻ','It’s very cheap.'],['expensive','/ɪkˈspensɪv/','đắt','That bag is expensive.'],['bread','/bred/','bánh mì','I want some bread.'],['milk','/mɪlk/','sữa','A litre of milk, please.'],['how much','/haʊ ˈmʌtʃ/','bao nhiêu (tiền)','How much is it?']],
 grammar:{body:'<p><b>Present continuous</b> = am/is/are + V-<b>ing</b>: việc đang xảy ra lúc nói.</p><ul><li>I’m <b>buying</b> milk. She <b>is reading</b>. They <b>are playing</b>.</li><li>Phủ định: He <b>isn’t</b> working. · Hỏi: <b>Are</b> you <b>watching</b> TV?</li><li>So sánh: I <b>play</b> football every week (thói quen) / I’m <b>playing</b> football now (đang xảy ra).</li></ul>',
  quiz:[{q:'Look! It ___ .',o:['rains','is raining','rain'],a:1,e:'“Look!” → đang xảy ra.'},{q:'What ___ you doing now?',o:['do','are','is'],a:1,e:'you → are + V-ing.'},{q:'He ___ TV at the moment.',o:["isn't watching","doesn't watching","not watching"],a:0,e:'isn’t + V-ing.'},{q:'I usually ___ tea, but today I’m drinking coffee.',o:['drink','am drinking','drinks'],a:0,e:'usually → present simple.'}]},
 listen:{dialog:[['A','Excuse me, how much is this bag?','Xin lỗi, cái túi này bao nhiêu?'],['B','It’s twenty dollars.','Hai mươi đô.'],['A','That’s expensive. Is there a cheaper one?','Đắt quá. Có cái rẻ hơn không?'],['B','Yes, this one is twelve dollars.','Có, cái này mười hai đô.'],['A','I’ll take it. Here you are.','Tôi lấy cái này. Của bạn đây.']],
  qs:[{q:'How much is the first bag?',o:['$12','$20','$30'],a:1,e:'“twenty dollars”.'},{q:'What does the customer buy?',o:['The $20 bag','The $12 bag','Nothing'],a:1,e:'“I’ll take it” (cái 12 đô).'}]},
 read:{text:'It is Saturday morning. Mai is at the market. She is buying vegetables and fruit. The tomatoes are cheap today, so she is buying two kilos. Her brother is waiting outside. He is drinking coffee and reading a newspaper. They are going home at ten o’clock.',
  qs:[{q:'Where is Mai?',o:['At school','At the market','At home'],a:1,e:'“at the market”.'},{q:'What is her brother doing?',o:['Buying fruit','Waiting and drinking coffee','Driving'],a:1,e:'“waiting outside … drinking coffee”.'},{q:'Why is she buying two kilos of tomatoes?',o:['They are cheap','She is hungry','They are big'],a:0,e:'“cheap today”.'}]},
 speak:{shadow:['How much is this? – It’s ten dollars.','I’m looking for a present for my mother.'],prompt:'Đóng vai người mua: hỏi giá, nói “rẻ / đắt” và quyết định mua hay không.'},
 write:{prompt:'Write what you and your family are doing right now (5 sentences).',min:35,model:'I am sitting at my desk and writing this text. My mother is cooking dinner in the kitchen. My father is watching the news. My brother is playing a game on his phone. We are not sleeping!'}},

{id:'a1u6',lv:'A1',title:'Quá khứ đơn – was/were & động từ có quy tắc',goal:'Kể về việc đã xảy ra hôm qua/tuần trước.',
 vocab:[['yesterday','/ˈjestɚdeɪ/','hôm qua','I worked yesterday.'],['last week','/læst wiːk/','tuần trước','We travelled last week.'],['visit','/ˈvɪzɪt/','thăm','I visited my grandmother.'],['play','/pleɪ/','chơi','They played football.'],['watch','/wɑːtʃ/','xem','We watched a film.'],['walk','/wɔːk/','đi bộ','I walked in the park.'],['stay','/steɪ/','ở lại','We stayed at home.'],['enjoy','/ɪnˈdʒɔɪ/','thích, tận hưởng','I enjoyed the trip.']],
 grammar:{body:'<p><b>be</b> quá khứ: I/he/she/it <b>was</b> · you/we/they <b>were</b>.</p><p>Động từ có quy tắc: V + <b>-ed</b> (work → worked, stay → stayed, study → studied).</p><ul><li>Phủ định: I <b>didn’t</b> work (didn’t + V nguyên mẫu).</li><li>Câu hỏi: <b>Did</b> you work? – Yes, I did.</li></ul>',
  quiz:[{q:'I ___ at home yesterday.',o:['was','were','am'],a:0,e:'I → was.'},{q:'They ___ football last Sunday.',o:['play','played','plays'],a:1,e:'last Sunday → quá khứ.'},{q:'She ___ watch TV last night.',o:["didn't",'not','doesn’t'],a:0,e:'didn’t + V.'},{q:'___ you visit your parents last week?',o:['Do','Did','Were'],a:1,e:'Did + you + V.'}]},
 listen:{dialog:[['A','What did you do last weekend?','Cuối tuần trước bạn làm gì?'],['B','I visited my grandmother. We cooked lunch together.','Mình thăm bà. Bọn mình nấu bữa trưa cùng nhau.'],['A','Did you enjoy it?','Bạn có vui không?'],['B','Yes, it was great! And you?','Có, rất vui! Còn bạn?'],['A','I stayed at home and watched films.','Mình ở nhà và xem phim.']],
  qs:[{q:'Who did B visit?',o:['A friend','His grandmother','His teacher'],a:1,e:'“visited my grandmother”.'},{q:'What did A do?',o:['Visited a friend','Went shopping','Stayed home and watched films'],a:2,e:'“stayed at home and watched films”.'}]},
 read:{text:'Last Saturday I got up early and walked to the park. It was sunny and warm. I played badminton with my friend Nam for an hour. After that we were hungry, so we visited a small restaurant. We ordered noodles and talked for a long time. I enjoyed the day very much.',
  qs:[{q:'What was the weather like?',o:['Rainy','Sunny and warm','Cold'],a:1,e:'“sunny and warm”.'},{q:'What did they play?',o:['Football','Tennis','Badminton'],a:2,e:'“played badminton”.'},{q:'Why did they go to a restaurant?',o:['They were hungry','It was raining','They were late'],a:0,e:'“we were hungry”.'}]},
 speak:{shadow:['I visited my grandmother last weekend.','We didn’t go out because it rained.'],prompt:'Kể về cuối tuần vừa rồi của bạn (5 câu).'},
 write:{prompt:'Write about your last weekend (6 sentences, past simple).',min:45,model:'Last weekend I stayed in Ho Chi Minh City. On Saturday I cleaned my flat and cooked lunch. In the afternoon I watched a film. On Sunday I visited my friend and we walked by the river. We talked and laughed a lot. I enjoyed the weekend.'}},

/* ============ A2 ============ */
{id:'a2u1',lv:'A2',title:'Quá khứ đơn bất quy tắc & kể chuyến đi',goal:'Kể một chuyến đi theo trình tự.',
 vocab:[['trip','/trɪp/','chuyến đi','The trip was amazing.'],['hotel','/hoʊˈtel/','khách sạn','We stayed in a small hotel.'],['airport','/ˈerpɔːrt/','sân bay','We arrived at the airport.'],['beach','/biːtʃ/','bãi biển','The beach was beautiful.'],['ticket','/ˈtɪkɪt/','vé','I bought two tickets.'],['sightseeing','/ˈsaɪtsiːɪŋ/','tham quan','We went sightseeing.'],['delay','/dɪˈleɪ/','chậm trễ','There was a delay.'],['journey','/ˈdʒɝːni/','hành trình','The journey took six hours.']],
 grammar:{body:'<p><b>Động từ bất quy tắc</b> (học thuộc): go→<b>went</b>, see→<b>saw</b>, buy→<b>bought</b>, eat→<b>ate</b>, take→<b>took</b>, have→<b>had</b>, come→<b>came</b>, make→<b>made</b>, get→<b>got</b>, write→<b>wrote</b>.</p><ul><li>Phủ định/hỏi dùng <b>didn’t / did + V nguyên mẫu</b>: I didn’t <b>go</b>. Did you <b>see</b> it?</li><li>Từ nối trình tự: first, then, after that, finally · <b>ago</b>: two years ago.</li></ul>',
  quiz:[{q:'We ___ to Da Nang last summer.',o:['go','went','goed'],a:1,e:'go → went.'},{q:'I ___ a lot of photos on the trip.',o:['taked','took','take'],a:1,e:'take → took.'},{q:'Did you ___ the museum?',o:['saw','see','seen'],a:1,e:'Did + V nguyên mẫu.'},{q:'She ___ a new phone two days ago.',o:['buyed','bought','buy'],a:1,e:'buy → bought.'}]},
 listen:{dialog:[['A','How was your trip to Hue?','Chuyến đi Huế của bạn thế nào?'],['B','Great! We went by train and arrived in the morning.','Tuyệt! Bọn mình đi tàu và đến vào buổi sáng.'],['A','What did you see?','Bạn xem những gì?'],['B','We saw the old palace and had lunch near the river.','Bọn mình xem cung điện cũ và ăn trưa gần sông.'],['A','Did you buy anything?','Bạn có mua gì không?'],['B','Yes, I bought a hat for my mother.','Có, mình mua một chiếc mũ cho mẹ.']],
  qs:[{q:'How did they travel to Hue?',o:['By plane','By train','By bus'],a:1,e:'“by train”.'},{q:'What did B buy?',o:['A hat','A book','A bag'],a:0,e:'“a hat for my mother”.'}]},
 read:{text:'Last August my family went to Phu Quoc for five days. The flight was late, so we arrived at the hotel at midnight. The next day we went to the beach and swam all morning. In the afternoon we took a boat to a small island and ate fresh seafood. On the last day we bought souvenirs at the night market. It was the best holiday we ever had.',
  qs:[{q:'Why did they arrive at midnight?',o:['The flight was late','They missed the boat','The hotel was far'],a:0,e:'“The flight was late”.'},{q:'What did they do on the island?',o:['Went shopping','Ate seafood','Slept'],a:1,e:'“ate fresh seafood”.'},{q:'Where did they buy souvenirs?',o:['At the airport','At the hotel','At the night market'],a:2,e:'“night market”.'}]},
 speak:{shadow:['We went to the beach and swam all morning.','What did you do on your last holiday?'],prompt:'Kể về chuyến đi gần nhất của bạn: đi đâu, làm gì, cảm thấy thế nào.'},
 write:{prompt:'Write about a trip you took (8 sentences). Use first, then, after that, finally.',min:70,model:'Last year I went to Da Lat with my friends. First, we took a bus and arrived in the afternoon. Then we checked in at a small hotel. After that we visited a flower garden and took many photos. In the evening we ate hot pot because it was cold. The next day we rode bicycles around the lake. Finally we bought strawberries and went home. It was a wonderful trip.'}},

{id:'a2u2',lv:'A2',title:'So sánh hơn & so sánh nhất',goal:'So sánh người, nơi chốn, sản phẩm.',
 vocab:[['expensive','/ɪkˈspensɪv/','đắt','This laptop is expensive.'],['crowded','/ˈkraʊdɪd/','đông đúc','The city is crowded.'],['quiet','/ˈkwaɪət/','yên tĩnh','The village is quiet.'],['modern','/ˈmɑːdɚn/','hiện đại','It’s a modern building.'],['popular','/ˈpɑːpjələr/','phổ biến','It’s a popular place.'],['comfortable','/ˈkʌmftəbl/','thoải mái','The bed is comfortable.'],['convenient','/kənˈviːniənt/','tiện lợi','The location is convenient.'],['similar','/ˈsɪmələr/','tương tự','The two phones are similar.']],
 grammar:{body:'<ul><li>Tính từ ngắn: <b>-er than / the -est</b>: cheap → cheaper → the cheapest; big → bigger; easy → easier.</li><li>Tính từ dài: <b>more … than / the most …</b>: more expensive, the most popular.</li><li>Bất quy tắc: good–better–best; bad–worse–worst.</li><li>Bằng nhau: <b>as … as</b> · Không bằng: <b>not as … as</b>.</li></ul>',
  quiz:[{q:'Hanoi is ___ than my hometown.',o:['big','bigger','more big'],a:1,e:'big → bigger.'},{q:'This is the ___ hotel in the city.',o:['more comfortable','most comfortable','comfortabler'],a:1,e:'So sánh nhất: the most + adj dài.'},{q:'The train is ___ than the bus.',o:['faster','more fast','fastest'],a:0,e:'fast → faster.'},{q:'This phone is ___ expensive as that one.',o:['as','more','than'],a:0,e:'as … as.'}]},
 listen:{dialog:[['A','Which laptop should I buy?','Mình nên mua laptop nào?'],['B','The blue one is cheaper, but the black one is faster.','Cái màu xanh rẻ hơn, nhưng cái màu đen nhanh hơn.'],['A','Which one is the lightest?','Cái nào nhẹ nhất?'],['B','The silver one is the lightest, but it’s the most expensive.','Cái màu bạc nhẹ nhất, nhưng cũng đắt nhất.'],['A','I think I’ll take the black one.','Mình nghĩ sẽ lấy cái màu đen.']],
  qs:[{q:'Which laptop is cheaper?',o:['The blue one','The black one','The silver one'],a:0,e:'“The blue one is cheaper”.'},{q:'Which laptop does A choose?',o:['Blue','Black','Silver'],a:1,e:'“I’ll take the black one.”'}]},
 read:{text:'Ho Chi Minh City and Da Lat are very different. Ho Chi Minh City is bigger and busier, and the traffic is much worse. Da Lat is smaller and quieter, and the weather is cooler. However, living in Ho Chi Minh City is more convenient because there are more jobs and shops. Many people say Da Lat is the most beautiful city in Vietnam.',
  qs:[{q:'Which city is quieter?',o:['Ho Chi Minh City','Da Lat'],a:1,e:'“Da Lat is smaller and quieter”.'},{q:'Why is Ho Chi Minh City more convenient?',o:['It is cooler','More jobs and shops','Less traffic'],a:1,e:'“more jobs and shops”.'},{q:'What do many people say about Da Lat?',o:['It is the biggest city','It is the most beautiful city','It is the cheapest city'],a:1,e:'“most beautiful”.'}]},
 speak:{shadow:['The train is faster, but the bus is cheaper.','This is the most comfortable chair in the office.'],prompt:'So sánh hai thành phố hoặc hai sản phẩm bạn biết (5 câu).'},
 write:{prompt:'Compare two places or two products (7 sentences). Use comparative and superlative forms.',min:60,model:'My hometown is smaller and quieter than Ho Chi Minh City. The air is cleaner and the food is cheaper. However, Ho Chi Minh City has more jobs and better hospitals. Travelling in my hometown is easier because there is less traffic. I think the city is more exciting, but my hometown is the most peaceful place for me.'}},

{id:'a2u3',lv:'A2',title:'Tương lai: going to, will, hiện tại tiếp diễn',goal:'Nói về kế hoạch, dự đoán, lời hứa.',
 vocab:[['plan','/plæn/','kế hoạch','What’s your plan for tomorrow?'],['decide','/dɪˈsaɪd/','quyết định','I decided to study English.'],['invite','/ɪnˈvaɪt/','mời','I’m inviting my friends.'],['appointment','/əˈpɔɪntmənt/','cuộc hẹn','I have a dentist appointment.'],['tomorrow','/təˈmɑːroʊ/','ngày mai','See you tomorrow.'],['next month','/nekst mʌnθ/','tháng sau','We’re moving next month.'],['hope','/hoʊp/','hy vọng','I hope it doesn’t rain.'],['probably','/ˈprɑːbəbli/','có lẽ','It will probably rain.']],
 grammar:{body:'<ul><li><b>be going to + V</b>: kế hoạch đã có / dự đoán có căn cứ. <i>I’m going to study tonight. Look at the sky – it’s going to rain.</i></li><li><b>will + V</b>: quyết định tức thời, lời hứa, dự đoán chung. <i>I’ll help you. I think it will be sunny.</i></li><li><b>Present continuous</b>: lịch hẹn đã sắp xếp. <i>I’m meeting Nam at 7.</i></li></ul>',
  quiz:[{q:'“I’m thirsty.” – “I ___ get you some water.”',o:['will','am going to','am getting'],a:0,e:'Quyết định tức thời → will.'},{q:'We ___ a party next Saturday. We’ve invited everyone.',o:['will have','are having','have'],a:1,e:'Đã sắp xếp → present continuous.'},{q:'Look at those clouds! It ___ rain.',o:['will','is going to','rains'],a:1,e:'Dự đoán có căn cứ → going to.'},{q:'I think prices ___ go up next year.',o:['will','are going','is'],a:0,e:'Ý kiến/dự đoán chung → will.'}]},
 listen:{dialog:[['A','What are you doing this weekend?','Cuối tuần này bạn làm gì?'],['B','I’m going to visit my parents in Can Tho.','Mình sẽ thăm bố mẹ ở Cần Thơ.'],['A','How are you going to get there?','Bạn đi bằng gì?'],['B','I’m taking the bus on Saturday morning.','Mình đi xe buýt sáng thứ Bảy.'],['A','That’s nice. I’ll call you on Sunday.','Hay đấy. Mình sẽ gọi bạn vào Chủ nhật.']],
  qs:[{q:'Where is B going?',o:['Can Tho','Hue','Da Nang'],a:0,e:'“Can Tho”.'},{q:'When will A call?',o:['On Saturday','On Sunday','Tomorrow'],a:1,e:'“I’ll call you on Sunday.”'}]},
 read:{text:'Next month Lan is starting a new job at a travel company. She is really excited. She is going to move to a flat near the office, so she will save time every day. She has an interview with her manager on Monday at nine. After that she will probably buy some new clothes. Lan hopes she will make a lot of new friends.',
  qs:[{q:'When does Lan start her new job?',o:['This week','Next month','Next year'],a:1,e:'“Next month”.'},{q:'Why is she moving?',o:['The flat is cheaper','To be near the office','To live with friends'],a:1,e:'“near the office … save time”.'},{q:'What will she probably do after Monday’s meeting?',o:['Buy clothes','Travel','Go home'],a:0,e:'“probably buy some new clothes”.'}]},
 speak:{shadow:['I’m going to start a new course next month.','I’ll call you later, I promise.'],prompt:'Nói về kế hoạch của bạn cho cuối tuần này và năm sau.'},
 write:{prompt:'Write about your plans for next year (7 sentences). Use going to and will.',min:60,model:'Next year I am going to improve my English. I’m going to study every day for 45 minutes. I will take an IELTS test in September. I hope I will get a better job. I’m also going to travel to Japan with my family. I think it will be an exciting year.'}},

{id:'a2u4',lv:'A2',title:'Hiện tại hoàn thành – kinh nghiệm & kết quả',goal:'Nói về trải nghiệm sống và việc vừa xảy ra.',
 vocab:[['experience','/ɪkˈspɪriəns/','kinh nghiệm','I have experience in sales.'],['abroad','/əˈbrɔːd/','ở nước ngoài','She has lived abroad.'],['try','/traɪ/','thử','Have you tried sushi?'],['finish','/ˈfɪnɪʃ/','hoàn thành','I’ve just finished my work.'],['lose','/luːz/','làm mất','I’ve lost my keys.'],['already','/ɔːlˈredi/','đã (rồi)','I’ve already eaten.'],['yet','/jet/','chưa','I haven’t called him yet.'],['ever','/ˈevɚ/','từng','Have you ever been to Japan?']],
 grammar:{body:'<p><b>Present perfect</b> = have/has + V3 (quá khứ phân từ): kết nối quá khứ với hiện tại.</p><ul><li>Trải nghiệm: <i>I have been to Japan. Have you <b>ever</b> tried sushi?</i> (ever/never)</li><li>Kết quả hiện tại: <i>I’ve lost my keys.</i> (bây giờ chưa tìm thấy)</li><li><b>already</b> (rồi) · <b>yet</b> (chưa, câu hỏi/phủ định) · <b>just</b> (vừa mới)</li><li>Không dùng với mốc thời gian đã xác định: ✗ I have seen him yesterday → ✓ I saw him yesterday.</li></ul>',
  quiz:[{q:'I ___ to Japan three times.',o:['went','have been','have go'],a:1,e:'Trải nghiệm → have been.'},{q:'She hasn’t finished the report ___.',o:['already','yet','ever'],a:1,e:'Phủ định → yet.'},{q:'Have you ___ eaten durian?',o:['ever','yet','just'],a:0,e:'Have you ever…?'},{q:'I ___ him yesterday.',o:['have seen','saw','has seen'],a:1,e:'yesterday → past simple.'}]},
 listen:{dialog:[['A','Have you ever been to Singapore?','Bạn từng đến Singapore chưa?'],['B','Yes, I’ve been there twice.','Rồi, mình đã đến hai lần.'],['A','Have you tried chili crab?','Bạn thử cua sốt ớt chưa?'],['B','Yes, and I loved it! Have you finished your report yet?','Rồi, và mình rất thích! Bạn xong báo cáo chưa?'],['A','Not yet. I’ve just started the last part.','Chưa. Mình vừa mới bắt đầu phần cuối.']],
  qs:[{q:'How many times has B been to Singapore?',o:['Once','Twice','Never'],a:1,e:'“twice”.'},{q:'Has A finished the report?',o:['Yes','No, not yet'],a:1,e:'“Not yet.”'}]},
 read:{text:'Minh is 30 years old and has lived in three countries. He has studied in Australia and has worked in Singapore. He has tried many kinds of food, but he has never eaten insects. He hasn’t visited Europe yet, but he has already bought a ticket to Paris for next spring. He has just started learning French.',
  qs:[{q:'How many countries has Minh lived in?',o:['Two','Three','Four'],a:1,e:'“three countries”.'},{q:'Has Minh visited Europe?',o:['Yes, many times','No, not yet','Only Paris'],a:1,e:'“hasn’t visited Europe yet”.'},{q:'What has he just started?',o:['Learning French','A new job','A trip'],a:0,e:'“just started learning French”.'}]},
 speak:{shadow:['I’ve never been to Europe, but I’d love to go.','Have you finished your homework yet?'],prompt:'Nói về 4 trải nghiệm bạn đã có (đã đi, đã ăn, đã học…).'},
 write:{prompt:'Write about things you have and haven’t done in your life (7 sentences).',min:60,model:'I have visited five provinces in Vietnam, but I haven’t been abroad yet. I have tried Japanese food, and I love it. I have never eaten frogs. I have studied English for three years. I have just finished a big project at work. I haven’t learned to swim yet, but I’m going to start soon.'}},

{id:'a2u5',lv:'A2',title:'Should / must / have to & câu điều kiện loại 1',goal:'Đưa lời khuyên, nói về nghĩa vụ, điều kiện có thể xảy ra.',
 vocab:[['advice','/ədˈvaɪs/','lời khuyên','Can I give you some advice?'],['rule','/ruːl/','quy tắc','Follow the rules.'],['safe','/seɪf/','an toàn','This area is safe.'],['dangerous','/ˈdeɪndʒərəs/','nguy hiểm','It’s dangerous to run here.'],['deadline','/ˈdedlaɪn/','hạn chót','The deadline is Friday.'],['ticket','/ˈtɪkɪt/','vé','You need a ticket.'],['pass','/pæs/','đỗ, vượt qua','I hope I pass the exam.'],['unless','/ənˈles/','trừ khi','I won’t go unless you come.']],
 grammar:{body:'<ul><li><b>should / shouldn’t</b>: lời khuyên. <i>You should sleep more.</i></li><li><b>must</b>: bắt buộc (mạnh, chủ quan) · <b>have to</b>: bắt buộc (do quy định) · <b>mustn’t</b>: cấm · <b>don’t have to</b>: không cần.</li><li><b>First conditional</b>: If + present simple, will + V. <i>If it rains, we will stay home.</i> · <b>unless</b> = if … not.</li></ul>',
  quiz:[{q:'You look tired. You ___ go to bed early.',o:['should','must not','have'],a:0,e:'Lời khuyên → should.'},{q:'You ___ park here. It’s forbidden.',o:["mustn't","don't have to","shouldn't have"],a:0,e:'Cấm → mustn’t.'},{q:'If I ___ time, I will call you.',o:['have','will have','had'],a:0,e:'If + present simple.'},{q:'We ___ wear a uniform at school. It’s the rule.',o:['have to','should to','can'],a:0,e:'Quy định → have to.'}]},
 listen:{dialog:[['A','I have an important exam tomorrow.','Mai mình có kỳ thi quan trọng.'],['B','You should go to bed early, then.','Vậy bạn nên đi ngủ sớm.'],['A','I know. If I don’t sleep, I won’t concentrate.','Mình biết. Nếu không ngủ, mình sẽ không tập trung được.'],['B','And you mustn’t use your phone in the exam.','Và bạn không được dùng điện thoại trong phòng thi.'],['A','Right. I have to leave it at the door.','Đúng. Mình phải để nó ở cửa.']],
  qs:[{q:'What does B advise A to do?',o:['Study all night','Go to bed early','Skip the exam'],a:1,e:'“go to bed early”.'},{q:'What must A do with the phone?',o:['Use it','Leave it at the door','Turn it up'],a:1,e:'“leave it at the door”.'}]},
 read:{text:'Staying healthy is not difficult. You should drink at least two litres of water a day and you shouldn’t eat too much sugar. If you exercise for thirty minutes every day, you will feel stronger. You don’t have to go to the gym; you can simply walk or ride a bike. You must see a doctor if you have a high fever for more than three days. Unless you sleep well, you won’t have enough energy.',
  qs:[{q:'How much water should you drink?',o:['One litre','At least two litres','Five litres'],a:1,e:'“at least two litres”.'},{q:'Do you have to go to the gym?',o:['Yes','No, walking is enough'],a:1,e:'“don’t have to go to the gym”.'},{q:'When must you see a doctor?',o:['After exercise','When you have a fever for over three days','Every day'],a:1,e:'“high fever for more than three days”.'}]},
 speak:{shadow:['You should drink more water and sleep earlier.','If it rains tomorrow, we won’t go to the beach.'],prompt:'Khuyên một người bạn muốn khỏe hơn: dùng should / shouldn’t / if.'},
 write:{prompt:'Write advice for a new employee at your company (7 sentences). Use should, must, have to, if.',min:60,model:'Welcome to the company! You should arrive at work before 8:30. You must wear your ID card every day. You have to finish your reports before the deadline. If you have a problem, you should ask your manager. You shouldn’t use your phone during meetings. If you work hard, you will learn very quickly.'}},

{id:'a2u6',lv:'A2',title:'Đếm được/không đếm được, lượng từ & nhà hàng',goal:'Gọi món, mua đồ, nói về số lượng.',
 vocab:[['ingredient','/ɪnˈɡriːdiənt/','nguyên liệu','What are the ingredients?'],['portion','/ˈpɔːrʃn/','khẩu phần','A large portion, please.'],['fresh','/freʃ/','tươi','The fish is fresh.'],['spicy','/ˈspaɪsi/','cay','Is it spicy?'],['waiter','/ˈweɪtɚ/','bồi bàn','The waiter is friendly.'],['order','/ˈɔːrdɚ/','gọi món','Are you ready to order?'],['menu','/ˈmenjuː/','thực đơn','Can I see the menu?'],['bill','/bɪl/','hóa đơn','The bill, please.']],
 grammar:{body:'<ul><li><b>Đếm được</b> (apple, egg): a/an, many, a few, several. <b>Không đếm được</b> (rice, water, sugar, money, information): much, a little, some, a lot of.</li><li><b>some</b> (khẳng định, lời mời) · <b>any</b> (phủ định, câu hỏi): <i>There isn’t any milk. Would you like some tea?</i></li><li><b>How many</b> + đếm được? · <b>How much</b> + không đếm được?</li><li>Trạng từ tần suất: always &gt; usually &gt; often &gt; sometimes &gt; rarely &gt; never.</li></ul>',
  quiz:[{q:'How ___ sugar do you want?',o:['many','much','few'],a:1,e:'sugar không đếm được.'},{q:'There aren’t ___ eggs in the fridge.',o:['some','any','much'],a:1,e:'Phủ định → any.'},{q:'I’d like ___ water, please.',o:['a','some','many'],a:1,e:'Yêu cầu lịch sự → some.'},{q:'He has ___ friends here, only two.',o:['a few','a little','much'],a:0,e:'friends đếm được → a few.'}]},
 listen:{dialog:[['A','Good evening. Are you ready to order?','Chào buổi tối. Bạn sẵn sàng gọi món chưa?'],['B','Yes. I’d like the grilled chicken, please.','Rồi. Cho tôi gà nướng.'],['A','Would you like some rice or salad with it?','Bạn muốn dùng thêm cơm hay salad?'],['B','Some salad, please. Is it spicy?','Salad nhé. Món này cay không?'],['A','Only a little. Anything to drink?','Chỉ hơi cay. Bạn uống gì không?'],['B','A glass of water, please.','Một ly nước.']],
  qs:[{q:'What does B order?',o:['Grilled chicken','Fish','Noodles'],a:0,e:'“grilled chicken”.'},{q:'What does B want with it?',o:['Rice','Salad','Bread'],a:1,e:'“Some salad”.'}]},
 read:{text:'Here is a simple recipe for fried rice. You need two cups of cooked rice, two eggs, a little oil, some vegetables and a few spring onions. First, heat the oil in a pan. Then add the eggs and stir. Add the rice and vegetables. Cook for five minutes. Finally, put a little salt on it and serve. There isn’t much work, and it is very cheap.',
  qs:[{q:'How many eggs do you need?',o:['One','Two','Three'],a:1,e:'“two eggs”.'},{q:'What is the first step?',o:['Add rice','Heat the oil','Add salt'],a:1,e:'“First, heat the oil”.'},{q:'What is true about the recipe?',o:['It is expensive','It needs a lot of work','It is cheap'],a:2,e:'“very cheap”.'}]},
 speak:{shadow:['I’d like a table for two, please.','Could we have the bill, please?'],prompt:'Đóng vai khách gọi món và vai nhân viên: hỏi món, hỏi cay không, xin hóa đơn.'},
 write:{prompt:'Write a recipe or a meal you like to cook (7 sentences). Use some, any, a little, a few.',min:60,model:'My favorite dish is egg noodles. You need some noodles, two eggs, a few vegetables and a little oil. First, boil the noodles for three minutes. Then fry the eggs. Add the vegetables and some soy sauce. Mix everything and serve hot. There isn’t much work, so it’s perfect for a busy evening.'}},

/* ============ B1 ============ */
{id:'b1u1',lv:'B1',title:'Quá khứ tiếp diễn vs quá khứ đơn – kể chuyện',goal:'Kể một câu chuyện có bối cảnh và sự kiện.',
 vocab:[['suddenly','/ˈsʌdnli/','đột nhiên','Suddenly, the lights went out.'],['meanwhile','/ˈmiːnwaɪl/','trong khi đó','Meanwhile, I was cooking.'],['notice','/ˈnoʊtɪs/','nhận thấy','I noticed a strange noise.'],['realize','/ˈriːəlaɪz/','nhận ra','I realized I was lost.'],['happen','/ˈhæpən/','xảy ra','What happened?'],['accident','/ˈæksɪdənt/','tai nạn','There was an accident.'],['luckily','/ˈlʌkɪli/','may mắn thay','Luckily, nobody was hurt.'],['unfortunately','/ʌnˈfɔːrtʃnətli/','không may','Unfortunately, we missed the train.']],
 grammar:{body:'<ul><li><b>Past continuous</b> (was/were + V-ing): bối cảnh, việc đang diễn ra trong quá khứ. <i>It was raining and I was walking home.</i></li><li><b>Past simple</b>: sự kiện xảy ra, cắt ngang. <i>Suddenly, a car stopped.</i></li><li><b>when</b> + past simple, <b>while</b> + past continuous: <i>While I was cooking, the phone rang.</i></li></ul>',
  quiz:[{q:'I ___ TV when the phone rang.',o:['watched','was watching','watch'],a:1,e:'Việc đang diễn ra bị cắt ngang.'},{q:'While she ___ , she saw an old friend.',o:['walked','was walking','walks'],a:1,e:'while + past continuous.'},{q:'We ___ dinner when the lights went out.',o:['had','were having','have had'],a:1,e:'Bối cảnh → past continuous.'},{q:'The bus ___ and everyone got off.',o:['stopped','was stopping','stops'],a:0,e:'Sự kiện ngắn → past simple.'}]},
 listen:{dialog:[['A','You look shocked. What happened?','Trông bạn sốc lắm. Chuyện gì vậy?'],['B','I was walking to work when a dog ran in front of me.','Mình đang đi bộ đi làm thì có con chó chạy ngang trước mặt.'],['A','Oh no! Were you hurt?','Ôi không! Bạn có bị thương không?'],['B','No, luckily I stopped in time, but I dropped my coffee.','Không, may là mình dừng kịp, nhưng làm rơi cà phê.'],['A','Poor you. Let me buy you another one.','Tội bạn. Để mình mua cho bạn ly khác.']],
  qs:[{q:'What was B doing when the dog ran out?',o:['Driving','Walking to work','Running'],a:1,e:'“was walking to work”.'},{q:'What did B drop?',o:['His phone','His bag','His coffee'],a:2,e:'“dropped my coffee”.'}]},
 read:{text:'Last winter I was travelling by train to Hanoi when something strange happened. It was snowing outside, and most passengers were sleeping. Suddenly, the train stopped in the middle of nowhere. I looked out of the window and noticed that a tree was lying across the track. While the staff were removing it, an old man offered me some tea. We talked for two hours about his life. When the train finally started again, I realized it was the best part of my journey.',
  qs:[{q:'Why did the train stop?',o:['It was too cold','A tree was on the track','The driver was ill'],a:1,e:'“a tree was lying across the track”.'},{q:'What were most passengers doing?',o:['Talking','Sleeping','Eating'],a:1,e:'“most passengers were sleeping”.'},{q:'What did the writer think of the delay in the end?',o:['It was terrible','It was the best part of the journey','It was boring'],a:1,e:'câu cuối.'}]},
 speak:{shadow:['I was walking home when it started to rain.','Suddenly, I realized I had left my keys at work.'],prompt:'Kể một sự việc bất ngờ đã xảy ra với bạn (dùng was/were + V-ing và past simple).'},
 write:{prompt:'Write a short story that begins: “It was a stormy night and I was …” (9 sentences).',min:90,model:'It was a stormy night and I was driving home from work. The rain was falling heavily and I couldn’t see the road clearly. Suddenly, a car stopped in front of me. I braked hard and stopped just in time. A woman was standing next to the car and waving. Her tyre was flat and her phone wasn’t working. I helped her change the tyre while the rain was still falling. When we finished, we were both wet but happy. She thanked me and I drove home smiling.'}},

{id:'b1u2',lv:'B1',title:'Hiện tại hoàn thành tiếp diễn & for/since',goal:'Nói về việc kéo dài đến hiện tại (công việc, học tập).',
 vocab:[['career','/kəˈrɪr/','sự nghiệp','She has built a strong career.'],['improve','/ɪmˈpruːv/','cải thiện','I want to improve my English.'],['achieve','/əˈtʃiːv/','đạt được','He achieved his goal.'],['colleague','/ˈkɑːliːɡ/','đồng nghiệp','My colleagues are helpful.'],['responsible','/rɪˈspɑːnsəbl/','chịu trách nhiệm','I’m responsible for the budget.'],['promote','/prəˈmoʊt/','thăng chức','She was promoted last year.'],['skill','/skɪl/','kỹ năng','Communication is a key skill.'],['recently','/ˈriːsntli/','gần đây','I’ve been busy recently.']],
 grammar:{body:'<ul><li><b>Present perfect continuous</b> = have/has been + V-ing: hành động bắt đầu trong quá khứ và <u>còn tiếp diễn</u> / vừa kết thúc, nhấn vào thời gian. <i>I’ve been learning English for two years.</i></li><li><b>for</b> + khoảng thời gian (for 3 months) · <b>since</b> + mốc thời gian (since 2021).</li><li>Khác biệt: <i>I’ve been reading this book (đang đọc, chưa xong)</i> vs <i>I’ve read this book (đã xong).</i></li></ul>',
  quiz:[{q:'I ___ here for five years.',o:['work','have been working','am working'],a:1,e:'for + thời gian, kéo dài → PP continuous (hoặc have worked).'},{q:'She has lived in Hanoi ___ 2019.',o:['for','since','from'],a:1,e:'since + mốc thời gian.'},{q:'They ___ for you for an hour!',o:['wait','have been waiting','waited'],a:1,e:'Vừa chờ và nhấn thời gian.'},{q:'How long ___ you been studying English?',o:['have','did','are'],a:0,e:'How long have you been…?'}]},
 listen:{dialog:[['A','How long have you been working here?','Bạn làm ở đây được bao lâu rồi?'],['B','I’ve been working here since 2020.','Mình làm ở đây từ năm 2020.'],['A','And what have you been doing recently?','Dạo này bạn đang làm gì?'],['B','I’ve been leading a new project for three months.','Ba tháng nay mình phụ trách một dự án mới.'],['A','That’s impressive. You’ve been working really hard.','Ấn tượng đấy. Bạn làm việc rất chăm chỉ.']],
  qs:[{q:'Since when has B worked there?',o:['2018','2020','2022'],a:1,e:'“since 2020”.'},{q:'How long has B been leading the project?',o:['One month','Three months','One year'],a:1,e:'“for three months”.'}]},
 read:{text:'Huong has been studying accounting at university since September. She has also been working part-time at a small firm for six months. At first she was nervous, but she has been learning quickly and her manager has been giving her more responsibility. Recently, she has been preparing for an important exam, so she has been getting up at five every morning. She says she has never worked so hard, but she has never felt so proud.',
  qs:[{q:'How long has Huong been working part-time?',o:['Two months','Six months','A year'],a:1,e:'“for six months”.'},{q:'Why has she been getting up at five?',o:['To go to work','To prepare for an exam','To exercise'],a:1,e:'“preparing for an important exam”.'},{q:'How does Huong feel now?',o:['Proud','Bored','Angry'],a:0,e:'“never felt so proud”.'}]},
 speak:{shadow:['I’ve been learning English for two years.','How long have you been living here?'],prompt:'Nói về công việc/học tập của bạn: đã làm bao lâu, gần đây đang làm gì.'},
 write:{prompt:'Write about your career or studies up to now (8 sentences). Use for, since and present perfect continuous.',min:80,model:'I have been working as an accountant for six years. I have been in my current company since 2021. Recently, I have been managing the monthly reports for three departments. I have been learning advanced Excel for four months, and my work has become faster. I have also been studying English every evening since January. I have been aiming for an IELTS score of 6.5. It’s hard, but I have been making progress.'}},

{id:'b1u3',lv:'B1',title:'Câu bị động (hiện tại, quá khứ, tương lai)',goal:'Mô tả quy trình và sự kiện khi tác nhân không quan trọng.',
 vocab:[['produce','/prəˈduːs/','sản xuất','The factory produces cars.'],['invent','/ɪnˈvent/','phát minh','The telephone was invented in 1876.'],['build','/bɪld/','xây dựng','The bridge was built in 1990.'],['export','/ɪkˈspɔːrt/','xuất khẩu','Vietnam exports coffee.'],['manufacture','/ˌmænjuˈfæktʃɚ/','chế tạo','The parts are manufactured in China.'],['discover','/dɪˈskʌvɚ/','khám phá','Penicillin was discovered by accident.'],['damage','/ˈdæmɪdʒ/','làm hư hại','The storm damaged many houses.'],['repair','/rɪˈper/','sửa chữa','The road will be repaired.']],
 grammar:{body:'<p><b>Passive</b> = be + V3. Tân ngữ của câu chủ động trở thành chủ ngữ.</p><ul><li>Present simple: Coffee <b>is grown</b> in Vietnam.</li><li>Past simple: The bridge <b>was built</b> in 1990.</li><li>Future: The road <b>will be repaired</b> next week.</li><li>Present perfect: The report <b>has been finished</b>.</li><li>Tác nhân (nếu cần): <b>by</b> + người/vật: <i>The book was written by a student.</i></li></ul>',
  quiz:[{q:'English ___ in many countries.',o:['speaks','is spoken','is speaking'],a:1,e:'English được nói → is spoken.'},{q:'The Eiffel Tower ___ in 1889.',o:['built','was built','is built'],a:1,e:'Quá khứ bị động.'},{q:'The new bridge ___ next year.',o:['will be opened','will open','opens'],a:0,e:'Tương lai bị động.'},{q:'Millions of bottles ___ every day.',o:['are produced','produce','is produced'],a:0,e:'Số nhiều → are produced.'}]},
 listen:{dialog:[['A','Where is your phone made?','Điện thoại của bạn được sản xuất ở đâu?'],['B','It’s designed in California but it’s assembled in Vietnam.','Nó được thiết kế ở California nhưng lắp ráp ở Việt Nam.'],['A','Are the parts made here too?','Các linh kiện cũng làm ở đây à?'],['B','No, most of them are imported from other countries.','Không, phần lớn được nhập từ nước khác.'],['A','So it’s a truly global product.','Vậy nó đúng là sản phẩm toàn cầu.']],
  qs:[{q:'Where is the phone assembled?',o:['California','Vietnam','China'],a:1,e:'“assembled in Vietnam”.'},{q:'Where do most parts come from?',o:['Vietnam','Other countries','California'],a:1,e:'“imported from other countries”.'}]},
 read:{text:'Coffee is one of the most popular drinks in the world. It is grown in more than 70 countries, and Vietnam is the second largest producer. The beans are picked by hand, dried in the sun and then sent to factories. There they are roasted and packed. Finally, the coffee is exported to markets around the world. Every year, about two billion cups are drunk every day. In the future, more coffee will be produced with sustainable methods.',
  qs:[{q:'How are the beans picked?',o:['By machine','By hand','By robots'],a:1,e:'“picked by hand”.'},{q:'What happens in the factories?',o:['Beans are planted','Beans are roasted and packed','Coffee is drunk'],a:1,e:'“roasted and packed”.'},{q:'What will happen in the future?',o:['Less coffee will be produced','More coffee will be produced sustainably','Coffee will be banned'],a:1,e:'câu cuối.'}]},
 speak:{shadow:['This product is made in Vietnam and exported to Europe.','The report will be finished by Friday.'],prompt:'Giải thích cách một món đồ/thức ăn quen thuộc được làm ra (dùng bị động).'},
 write:{prompt:'Describe how a product is made or a process at your workplace (8 sentences, passive voice).',min:80,model:'Rice is one of the most important crops in Vietnam. First, the seeds are planted in wet fields. Then the young plants are moved to larger fields. After four months, the rice is harvested. It is dried in the sun and then taken to a mill. There the husks are removed and the rice is polished. Finally, it is packed and sold in shops or exported abroad.'}},

{id:'b1u4',lv:'B1',title:'Câu điều kiện loại 0–2 & used to',goal:'Nói về giả định, thói quen quá khứ, lời khuyên.',
 vocab:[['habit','/ˈhæbɪt/','thói quen','Reading is a good habit.'],['lifestyle','/ˈlaɪfstaɪl/','lối sống','A healthy lifestyle matters.'],['imagine','/ɪˈmædʒɪn/','tưởng tượng','Imagine you won a prize.'],['opportunity','/ˌɑːpɚˈtuːnəti/','cơ hội','It’s a great opportunity.'],['effort','/ˈefɚt/','nỗ lực','It takes a lot of effort.'],['gradually','/ˈɡrædʒuəli/','dần dần','Gradually, I got used to it.'],['improve','/ɪmˈpruːv/','cải thiện','My English improved.'],['advantage','/ədˈvæntɪdʒ/','ưu điểm','One advantage is low cost.']],
 grammar:{body:'<ul><li><b>Loại 0</b>: If + present, present (sự thật). <i>If you heat ice, it melts.</i></li><li><b>Loại 1</b>: If + present, will + V (có thể xảy ra).</li><li><b>Loại 2</b>: If + <b>past simple</b>, <b>would</b> + V (không có thật/khó xảy ra ở hiện tại). <i>If I won the lottery, I would travel the world.</i> (If I <b>were</b> you, I’d…)</li><li><b>used to + V</b>: thói quen/trạng thái trong quá khứ nay không còn. <i>I used to smoke.</i> · <b>get used to + V-ing</b>: dần quen.</li></ul>',
  quiz:[{q:'If I ___ more time, I would learn Spanish.',o:['have','had','would have'],a:1,e:'Loại 2: If + past simple.'},{q:'If I were you, I ___ take that job.',o:['will','would','am going to'],a:1,e:'Lời khuyên → would.'},{q:'I ___ live in a small village when I was a child.',o:['use to','used to','was used to'],a:1,e:'used to + V.'},{q:'I’m not used ___ up so early.',o:['to get','to getting','getting'],a:1,e:'be used to + V-ing.'}]},
 listen:{dialog:[['A','What would you do if you won a million dollars?','Bạn sẽ làm gì nếu trúng một triệu đô?'],['B','I’d buy a house and travel for a year.','Mình sẽ mua nhà và đi du lịch một năm.'],['A','I used to dream about that too.','Mình cũng từng mơ như thế.'],['B','What do you dream about now?','Giờ bạn mơ ước điều gì?'],['A','If I had a quiet place, I would write a book.','Nếu có nơi yên tĩnh, mình sẽ viết một cuốn sách.']],
  qs:[{q:'What would B do with a million dollars?',o:['Buy a house and travel','Start a company','Give it away'],a:0,e:'“buy a house and travel”.'},{q:'What would A do with a quiet place?',o:['Write a book','Sleep','Study'],a:0,e:'“write a book”.'}]},
 read:{text:'When I was a child, I used to spend every summer in my grandparents’ village. We used to swim in the river and catch fish. Now I live in a big city and I’m not used to the noise. If I had more free time, I would go back there every month. If people spent less time on their phones, they would notice how beautiful nature is. In my opinion, if you get out of the city regularly, you feel much calmer.',
  qs:[{q:'What did the writer use to do in summer?',o:['Swim in the river','Study','Work'],a:0,e:'“swim in the river”.'},{q:'What would the writer do with more free time?',o:['Go to the village every month','Buy a house','Work more'],a:0,e:'“go back there every month”.'},{q:'What does the writer think about getting out of the city?',o:['It makes people calmer','It is boring','It is expensive'],a:0,e:'“feel much calmer”.'}]},
 speak:{shadow:['If I won the lottery, I would travel the world.','I used to walk to school when I was young.'],prompt:'Nói: nếu bạn có thêm 2 giờ mỗi ngày bạn sẽ làm gì? Và bạn từng có thói quen gì hồi nhỏ?'},
 write:{prompt:'Write about your life in the past and imagine changes (8 sentences). Use used to and if + would.',min:80,model:'When I was a child, I used to live in a small town near the sea. I used to play football on the beach every evening. Now I live in a big city and I am not used to the traffic. If I lived near the sea, I would swim every day. If I had a bigger salary, I would buy a house with a garden. I would also travel more often. However, if I moved away, I would miss my friends.'}},

{id:'b1u5',lv:'B1',title:'Câu tường thuật & câu hỏi gián tiếp',goal:'Thuật lại lời người khác; hỏi lịch sự.',
 vocab:[['announce','/əˈnaʊns/','thông báo','The manager announced a new plan.'],['explain','/ɪkˈspleɪn/','giải thích','Can you explain this rule?'],['suggest','/səˈdʒest/','đề xuất','I suggest going by train.'],['mention','/ˈmenʃn/','đề cập','He mentioned a problem.'],['promise','/ˈprɑːmɪs/','hứa','She promised to help.'],['admit','/ədˈmɪt/','thừa nhận','He admitted his mistake.'],['reply','/rɪˈplaɪ/','trả lời','I’ll reply tomorrow.'],['complain','/kəmˈpleɪn/','phàn nàn','Customers complained.']],
 grammar:{body:'<p><b>Reported speech</b>: lùi một thì; đổi đại từ và trạng từ.</p><ul><li>“I <b>am</b> tired.” → She said she <b>was</b> tired.</li><li>“I <b>will</b> call.” → He said he <b>would</b> call.</li><li>“I <b>have finished</b>.” → She said she <b>had finished</b>.</li><li>Câu hỏi Yes/No: <i>He asked <b>if/whether</b> I was ready.</i> Wh-: <i>She asked where I lived.</i> (không đảo ngữ)</li><li>Câu hỏi gián tiếp lịch sự: <i>Could you tell me <b>where the station is</b>?</i> (không dùng “is the station”).</li></ul>',
  quiz:[{q:'“I’m busy,” he said. → He said he ___ busy.',o:['is','was','has been'],a:1,e:'am → was.'},{q:'“I will call you.” → She said she ___ call me.',o:['will','would','can'],a:1,e:'will → would.'},{q:'“Where do you live?” → He asked me where I ___ .',o:['live','lived','do live'],a:1,e:'Lùi thì, không đảo ngữ.'},{q:'Could you tell me where ___ ?',o:['is the bank','the bank is','does the bank'],a:1,e:'Câu hỏi gián tiếp: trật tự câu khẳng định.'}]},
 listen:{dialog:[['A','What did the manager say in the meeting?','Quản lý đã nói gì trong cuộc họp?'],['B','She said the deadline had moved to Friday.','Cô ấy nói hạn chót đã dời sang thứ Sáu.'],['A','Did she say why?','Cô ấy có nói lý do không?'],['B','She explained that the client wanted more details.','Cô giải thích rằng khách hàng muốn thêm chi tiết.'],['A','And did she ask us to work overtime?','Vậy cô có yêu cầu tăng ca không?'],['B','No, but she asked if we could finish earlier.','Không, nhưng cô hỏi liệu ta có thể xong sớm hơn không.']],
  qs:[{q:'When is the new deadline?',o:['Wednesday','Thursday','Friday'],a:2,e:'“moved to Friday”.'},{q:'Why did the deadline change?',o:['The client wanted more details','Staff were ill','A holiday'],a:0,e:'“client wanted more details”.'}]},
 read:{text:'Yesterday I had a strange phone call. A man said he was calling from the bank and asked if I had a moment. He told me that there was a problem with my account and asked me to give him my password. I explained that I never shared my password with anyone. He replied that it was urgent, but I said I would go to the bank myself. Later the bank confirmed that they hadn’t called me. They advised me never to give personal information over the phone.',
  qs:[{q:'What did the caller ask for?',o:['Money','My password','My address'],a:1,e:'“give him my password”.'},{q:'What did the writer say he would do?',o:['Go to the bank','Call the police','Give the password'],a:0,e:'“I would go to the bank myself”.'},{q:'What did the bank advise?',o:['Never share personal information by phone','Change accounts','Use more passwords'],a:0,e:'câu cuối.'}]},
 speak:{shadow:['She said that the meeting had been cancelled.','Could you tell me where the nearest bank is?'],prompt:'Thuật lại một cuộc trò chuyện gần đây: ai nói gì, ai hỏi gì.'},
 write:{prompt:'Report a conversation you had recently (8 sentences). Use said, told, asked.',min:80,model:'Yesterday my manager called me into her office. She said that she was very happy with my work. She told me that the company was going to open a new branch. She asked if I wanted to lead the accounting team there. I said that I needed some time to think. She replied that I could give her an answer by Friday. I explained that I would talk to my family first. She said that she understood.'}},

{id:'b1u6',lv:'B1',title:'Mệnh đề quan hệ, tính từ -ed/-ing & từ nối',goal:'Nối ý, mô tả chi tiết, lập luận mạch lạc.',
 vocab:[['exciting','/ɪkˈsaɪtɪŋ/','thú vị (gây hứng thú)','The trip was exciting.'],['excited','/ɪkˈsaɪtɪd/','hào hứng','I’m excited about it.'],['boring','/ˈbɔːrɪŋ/','nhàm chán','The film was boring.'],['bored','/bɔːrd/','buồn chán','I felt bored.'],['however','/haʊˈevɚ/','tuy nhiên','However, it was expensive.'],['although','/ɔːlˈðoʊ/','mặc dù','Although it rained, we went.'],['therefore','/ˈðerfɔːr/','vì vậy','Therefore, we changed plans.'],['in addition','/ɪn əˈdɪʃn/','ngoài ra','In addition, it is cheap.']],
 grammar:{body:'<ul><li><b>who</b> (người) · <b>which</b> (vật) · <b>that</b> (người/vật) · <b>whose</b> (sở hữu) · <b>where</b> (nơi chốn).</li><li>Xác định (không dấu phẩy): <i>The man who lives next door is a doctor.</i> · Không xác định (có dấu phẩy): <i>My brother, who lives in Hue, is a doctor.</i></li><li><b>-ed</b> = cảm xúc của người (I am bored) · <b>-ing</b> = tính chất của vật/việc (The film is boring).</li><li>Từ nối: <b>although/even though</b> + mệnh đề · <b>despite/in spite of</b> + danh từ/V-ing · <b>however</b>, <b>therefore</b>, <b>in addition</b>, <b>because of</b>.</li></ul>',
  quiz:[{q:'The woman ___ works here is my aunt.',o:['who','which','whose'],a:0,e:'Người + chủ ngữ → who.'},{q:'The film was ___ . I almost fell asleep.',o:['bored','boring','bore'],a:1,e:'Tính chất của phim → boring.'},{q:'___ it was raining, we went for a walk.',o:['Despite','Although','Because'],a:1,e:'Although + mệnh đề.'},{q:'___ the bad weather, the flight left on time.',o:['Although','Despite','However'],a:1,e:'Despite + danh từ.'}]},
 listen:{dialog:[['A','How was the concert?','Buổi hòa nhạc thế nào?'],['B','Amazing! The singer who performed first was fantastic.','Tuyệt vời! Ca sĩ biểu diễn đầu tiên rất xuất sắc.'],['A','Was it crowded?','Có đông không?'],['B','Yes, although the tickets were expensive, the hall was full.','Có, dù vé đắt nhưng hội trường vẫn đầy.'],['A','I’m so jealous. I was really bored at home.','Mình ghen tị quá. Mình ở nhà chán muốn chết.']],
  qs:[{q:'How was the concert?',o:['Boring','Amazing','Too short'],a:1,e:'“Amazing”.'},{q:'How was the hall?',o:['Empty','Full','Small'],a:1,e:'“the hall was full”.'}]},
 read:{text:'I recently visited a museum which had just opened in my city. It was a surprising place because the exhibits, which were mostly interactive, allowed visitors to touch and try things. I was amazed by a room where you could listen to sounds from the past. Although the ticket was expensive, I didn’t feel bored for a second. However, the cafe was too crowded. In addition, there were not enough seats. Despite these problems, I would recommend it to anyone who loves history.',
  qs:[{q:'What was special about the exhibits?',o:['They were old','They were interactive','They were free'],a:1,e:'“mostly interactive”.'},{q:'What was a problem?',o:['The museum was closed','The cafe was crowded','The ticket was free'],a:1,e:'“the cafe was too crowded”.'},{q:'Would the writer recommend it?',o:['Yes','No'],a:0,e:'“I would recommend it”.'}]},
 speak:{shadow:['Although it was expensive, it was worth it.','The man who helped me was very kind.'],prompt:'Nêu ưu và nhược điểm của một nơi bạn từng đến, dùng although, however, in addition.'},
 write:{prompt:'Review a place, film or restaurant (9 sentences). Use who/which, although, however, -ed/-ing adjectives.',min:90,model:'Last week I visited a restaurant which specialises in seafood. Although it was quite far from my house, the trip was worth it. The chef, who trained in France, prepared an amazing fish soup. The service was excellent, and the staff were very friendly. However, the prices were higher than I expected. In addition, the restaurant was very crowded, so we waited for forty minutes. Despite these problems, I felt satisfied and I will definitely go back.'}},

/* ============ B2 ============ */
{id:'b2u1',lv:'B2',title:'Thì kể chuyện: quá khứ hoàn thành & quá khứ hoàn thành tiếp diễn',goal:'Kể chuyện phức tạp, sắp xếp thứ tự sự kiện.',
 vocab:[['eventually','/ɪˈventʃuəli/','cuối cùng','Eventually, he got the job.'],['previously','/ˈpriːviəsli/','trước đó','Previously, I had worked abroad.'],['overcome','/ˌoʊvɚˈkʌm/','vượt qua','She overcame many difficulties.'],['struggle','/ˈstrʌɡl/','vật lộn, khó khăn','He struggled to find work.'],['determined','/dɪˈtɝːmɪnd/','quyết tâm','I was determined to succeed.'],['reluctantly','/rɪˈlʌktəntli/','miễn cưỡng','She reluctantly agreed.'],['setback','/ˈsetbæk/','trở ngại','It was a serious setback.'],['turn out','/tɝːn aʊt/','hóa ra','It turned out to be true.']],
 grammar:{body:'<ul><li><b>Past perfect</b> (had + V3): việc xảy ra <u>trước</u> một mốc/việc khác trong quá khứ. <i>When I arrived, the meeting had already started.</i></li><li><b>Past perfect continuous</b> (had been + V-ing): nhấn vào quá trình kéo dài trước mốc đó. <i>She was exhausted because she had been working all night.</i></li><li>Kể chuyện phối hợp: past simple (sự kiện chính) + past continuous (bối cảnh) + past perfect (nền trước đó).</li></ul>',
  quiz:[{q:'By the time we arrived, the film ___ .',o:['started','had started','was starting'],a:1,e:'Trước mốc “arrived” → past perfect.'},{q:'He was tired because he ___ all day.',o:['worked','had been working','has worked'],a:1,e:'Quá trình kéo dài trước → had been V-ing.'},{q:'She realized she ___ her passport at home.',o:['left','had left','was leaving'],a:1,e:'Trước lúc nhận ra.'},{q:'After they ___ dinner, they went for a walk.',o:['had finished','were finishing','finish'],a:0,e:'After + past perfect.'}]},
 listen:{dialog:[['A','So how did you end up moving to Canada?','Vậy sao bạn lại chuyển sang Canada?'],['B','I had been working in Hanoi for five years when I got an offer.','Mình đã làm ở Hà Nội năm năm thì nhận được lời mời.'],['A','Had you planned to leave?','Bạn đã định rời đi chưa?'],['B','Not really. I had never thought about it, but I was determined to try.','Không hẳn. Mình chưa bao giờ nghĩ đến, nhưng mình quyết tâm thử.'],['A','And it turned out well?','Và mọi thứ ổn chứ?'],['B','Eventually, yes. The first year was a struggle.','Cuối cùng là ổn. Năm đầu rất vất vả.']],
  qs:[{q:'How long had B worked in Hanoi?',o:['Two years','Five years','Ten years'],a:1,e:'“for five years”.'},{q:'How was the first year?',o:['Easy','A struggle','Boring'],a:1,e:'“a struggle”.'}]},
 read:{text:'When Mai started her first job at a bank, she hadn’t worked with international clients before. She had been studying English for years, but she had never spoken it in a business meeting. On her first day, she was so nervous that she forgot everything she had prepared. Fortunately, her manager, who had been through a similar experience, reassured her. Within a year, she had become the team’s main contact for overseas clients. Looking back, she realized that the fear she had felt at the beginning had been the best motivation.',
  qs:[{q:'Why was Mai nervous on the first day?',o:['She was late','She had never spoken English in a business meeting','She hated her manager'],a:1,e:'câu 2.'},{q:'What had happened within a year?',o:['She had left the bank','She had become the main contact for overseas clients','She had been fired'],a:1,e:'“had become the team’s main contact”.'},{q:'What does she think about her fear now?',o:['It was useless','It was good motivation','It was dangerous'],a:1,e:'câu cuối.'}]},
 speak:{shadow:['By the time I got there, everyone had left.','I had been waiting for an hour when she finally called.'],prompt:'Kể một trải nghiệm khó khăn, dùng ít nhất 3 câu past perfect.'},
 write:{prompt:'Write a narrative about an unforgettable experience (10 sentences). Use past simple, past continuous, past perfect.',min:110,model:'I will never forget the day I missed my flight. I had packed the night before, but I had forgotten to set my alarm. When I woke up, it was already seven and the flight had left. I was furious with myself. I had been looking forward to the trip for months. While I was searching for another flight, I met a stranger who had been in the same situation. We shared a taxi to another airport and eventually caught a later flight. Although the day had started badly, it turned out to be one of the most memorable of my life.'}},

{id:'b2u2',lv:'B2',title:'Điều kiện loại 3, hỗn hợp & câu ước',goal:'Nói về hối tiếc, giả định trong quá khứ và hiện tại.',
 vocab:[['regret','/rɪˈɡret/','hối tiếc','I regret not studying.'],['consequence','/ˈkɑːnsɪkwens/','hậu quả','Every action has consequences.'],['opportunity','/ˌɑːpɚˈtuːnəti/','cơ hội','I missed the opportunity.'],['mistake','/mɪˈsteɪk/','sai lầm','It was a big mistake.'],['alternative','/ɔːlˈtɝːnətɪv/','giải pháp thay thế','Is there an alternative?'],['prevent','/prɪˈvent/','ngăn ngừa','We could have prevented it.'],['blame','/bleɪm/','đổ lỗi','Don’t blame yourself.'],['in hindsight','/ɪn ˈhaɪndsaɪt/','nhìn lại thì','In hindsight, I was wrong.']],
 grammar:{body:'<ul><li><b>Loại 3</b>: If + past perfect, would have + V3 (trái sự thật ở quá khứ). <i>If I had studied harder, I would have passed.</i></li><li><b>Hỗn hợp</b>: If + past perfect, would + V (quá khứ → hiện tại). <i>If I had taken that job, I would be rich now.</i></li><li><b>wish / if only</b>: hiện tại → past simple (<i>I wish I had more time</i>); quá khứ → past perfect (<i>I wish I had left earlier</i>); phàn nàn → would (<i>I wish he would stop</i>).</li></ul>',
  quiz:[{q:'If she ___ the map, she wouldn’t have got lost.',o:['read','had read','has read'],a:1,e:'Loại 3: had + V3.'},{q:'If I ___ to university, I would have a better job now.',o:['went','had gone','would go'],a:1,e:'Hỗn hợp: If + past perfect.'},{q:'I wish I ___ more money when I was young.',o:['saved','had saved','would save'],a:1,e:'Quá khứ → past perfect.'},{q:'If only he ___ complaining all the time!',o:['stops','would stop','stopped'],a:1,e:'Phàn nàn hành vi → would.'}]},
 listen:{dialog:[['A','I still regret not taking that job in Tokyo.','Mình vẫn tiếc vì không nhận việc ở Tokyo.'],['B','If you had accepted it, you would have moved last year.','Nếu nhận thì bạn đã chuyển đi từ năm ngoái.'],['A','Yes, and I would be living there now.','Ừ, và giờ mình đã đang sống ở đó.'],['B','Do you think you would have been happier?','Bạn nghĩ mình sẽ hạnh phúc hơn chứ?'],['A','Maybe. I wish I hadn’t been so afraid.','Có lẽ. Giá mà mình đã không quá sợ.']],
  qs:[{q:'What does A regret?',o:['Not taking a job in Tokyo','Leaving Tokyo','Buying a house'],a:0,e:'câu 1.'},{q:'What does A wish?',o:['He hadn’t been so afraid','He had more money','He lived nearby'],a:0,e:'“I wish I hadn’t been so afraid.”'}]},
 read:{text:'Many people look back on their lives and think about what might have been. If they had chosen a different career, would they be happier today? Psychologists say such thoughts, known as counterfactual thinking, can be both helpful and harmful. On the one hand, if we had not learned from our mistakes, we would repeat them. On the other hand, if we constantly wish we had done things differently, we may forget to enjoy the present. The key, experts argue, is to use regret as a guide, not as a punishment.',
  qs:[{q:'What is counterfactual thinking?',o:['Thinking about what might have been','Planning the future','Counting things'],a:0,e:'câu 3 (định nghĩa).'},{q:'What is a benefit of regret?',o:['We learn from mistakes','We become richer','We forget the past'],a:0,e:'“learned from our mistakes”.'},{q:'What do experts recommend?',o:['Ignoring regret','Using regret as a guide','Punishing yourself'],a:1,e:'câu cuối.'}]},
 speak:{shadow:['If I had known, I would have acted differently.','I wish I had started learning English earlier.'],prompt:'Nói về một quyết định bạn từng hối tiếc và điều bạn sẽ làm khác đi.'},
 write:{prompt:'Write about a decision you regret and how your life might be different (9 sentences). Use third and mixed conditionals and wish.',min:100,model:'I sometimes regret not studying abroad after university. If I had applied for the scholarship, I would have improved my English much faster. I might have met people from all over the world. I wish I had been braver at that time. If I had left, I would probably be working in a different field now. However, if I hadn’t stayed, I wouldn’t have met my current colleagues, who have become close friends. In hindsight, every choice has consequences, and I try to learn from them.'}},

{id:'b2u3',lv:'B2',title:'Bị động nâng cao & thể sai khiến (have something done)',goal:'Nói khách quan, trang trọng; nhờ người khác làm việc.',
 vocab:[['repair','/rɪˈper/','sửa chữa','I had my car repaired.'],['install','/ɪnˈstɔːl/','lắp đặt','We had a new system installed.'],['renovate','/ˈrenəveɪt/','cải tạo','They renovated the house.'],['appoint','/əˈpɔɪnt/','bổ nhiệm','She was appointed manager.'],['inspect','/ɪnˈspekt/','kiểm tra','The building was inspected.'],['approve','/əˈpruːv/','phê duyệt','The plan was approved.'],['reportedly','/rɪˈpɔːrtɪdli/','theo báo cáo','Reportedly, prices will rise.'],['ban','/bæn/','cấm','Plastic bags were banned.']],
 grammar:{body:'<ul><li><b>Passive nâng cao</b>: is being built (đang xây) · has been approved · will have been completed · must be checked · can’t be done.</li><li><b>Passive báo cáo</b>: <i>It is said that…</i> / <i>He is said to be…</i> / <i>The plan is believed to have failed.</i></li><li><b>Have/get something done</b> (nhờ người khác làm): <i>I had my hair cut. We are having the kitchen painted. She got her laptop repaired.</i></li></ul>',
  quiz:[{q:'The new hospital ___ at the moment.',o:['is being built','builds','has built'],a:0,e:'Đang xây → is being built.'},{q:'I ___ my teeth checked twice a year.',o:['have','make','am'],a:0,e:'have + tân ngữ + V3.'},{q:'The results ___ by next Monday.',o:['will have been announced','will announce','announced'],a:0,e:'Tương lai hoàn thành bị động.'},{q:'He is said ___ a millionaire.',o:['to be','being','is'],a:0,e:'He is said to + V.'}]},
 listen:{dialog:[['A','Your office looks different!','Văn phòng bạn trông khác quá!'],['B','Yes, we’ve just had it renovated.','Ừ, bọn mình vừa cải tạo xong.'],['A','Did you do it yourselves?','Bạn tự làm à?'],['B','No, the work was done by a local company. The walls were painted and new lights were installed.','Không, công ty địa phương làm. Tường được sơn và đèn mới được lắp.'],['A','How long did it take?','Mất bao lâu?'],['B','It’s being finished this week. The furniture will be delivered on Friday.','Tuần này sẽ xong. Đồ nội thất sẽ được giao vào thứ Sáu.']],
  qs:[{q:'Who did the renovation?',o:['The staff','A local company','The owner'],a:1,e:'“done by a local company”.'},{q:'When will the furniture arrive?',o:['Monday','Wednesday','Friday'],a:2,e:'“delivered on Friday”.'}]},
 read:{text:'The city council has announced that the old town centre will be renovated over the next two years. According to the plan, historic buildings will be repaired, and traffic will be restricted to pedestrian zones. It is estimated that more than 200 jobs will be created. However, some shop owners are worried; they say business has been affected by the noise. The project is expected to have been completed by 2028. The council insists that residents will be consulted at every stage.',
  qs:[{q:'What will happen to the historic buildings?',o:['Be demolished','Be repaired','Be sold'],a:1,e:'“will be repaired”.'},{q:'Why are some shop owners worried?',o:['Business has been affected by noise','Rent will rise','They must leave'],a:0,e:'“affected by the noise”.'},{q:'When is the project expected to finish?',o:['2026','2028','2030'],a:1,e:'“by 2028”.'}]},
 speak:{shadow:['We had the whole system replaced last month.','The bridge is said to have been built in 1920.'],prompt:'Mô tả một dự án hoặc thay đổi ở nơi bạn sống/làm việc bằng câu bị động.'},
 write:{prompt:'Write a formal report describing changes made at a workplace (9 sentences, passive).',min:100,model:'Several improvements have been made in our office this year. The old computers were replaced, and a new accounting system was installed. The meeting room was renovated and more chairs were added. Staff training is being organised every month. It is believed that these changes have increased productivity. In the coming months, the parking area will be enlarged and a canteen will be opened. It is hoped that all works will have been completed by December.'}},

{id:'b2u4',lv:'B2',title:'Tương lai hoàn thành/tiếp diễn & suy đoán (must/might/can’t have)',goal:'Dự đoán, suy luận từ bằng chứng.',
 vocab:[['forecast','/ˈfɔːrkæst/','dự báo','The forecast says rain.'],['likely','/ˈlaɪkli/','có khả năng','It’s likely to rain.'],['assume','/əˈsuːm/','giả định','I assume you’re right.'],['evidence','/ˈevɪdəns/','bằng chứng','There’s no evidence.'],['probable','/ˈprɑːbəbl/','có thể xảy ra','It’s highly probable.'],['certain','/ˈsɝːtn/','chắc chắn','I’m certain of it.'],['by then','/baɪ ˈðen/','đến lúc đó','By then, I’ll have finished.'],['in the long run','/ɪn ðə lɔːŋ rʌn/','về lâu dài','It’s cheaper in the long run.']],
 grammar:{body:'<ul><li><b>Future continuous</b> (will be + V-ing): đang diễn ra tại mốc tương lai. <i>This time tomorrow I’ll be flying to Tokyo.</i></li><li><b>Future perfect</b> (will have + V3): sẽ hoàn thành trước mốc tương lai. <i>By 2030 I will have saved enough.</i></li><li><b>Suy đoán quá khứ</b>: <b>must have + V3</b> (chắc chắn đã) · <b>might/could have + V3</b> (có thể đã) · <b>can’t/couldn’t have + V3</b> (chắc chắn không). <i>He must have missed the bus.</i></li></ul>',
  quiz:[{q:'By next June, I ___ my degree.',o:['will finish','will have finished','am finishing'],a:1,e:'By + mốc → future perfect.'},{q:'This time tomorrow we ___ on the beach.',o:['will lie','will be lying','lie'],a:1,e:'Future continuous.'},{q:'The lights are off. They ___ gone out.',o:['must have','can have','should be'],a:0,e:'Suy luận chắc chắn về quá khứ.'},{q:'He ___ have done it. He was abroad at the time.',o:["can't",'must','might'],a:0,e:'Loại trừ chắc chắn → can’t have.'}]},
 listen:{dialog:[['A','Where’s Nam? He’s an hour late.','Nam đâu rồi? Anh ấy trễ một giờ.'],['B','He must have missed his train.','Chắc anh ấy lỡ chuyến tàu.'],['A','Or he might have forgotten the meeting.','Hoặc anh ấy có thể quên cuộc họp.'],['B','He can’t have forgotten. He set a reminder yesterday.','Không thể quên được. Hôm qua anh ấy đã đặt nhắc nhở.'],['A','By the time he arrives, we’ll have finished.','Lúc anh ấy đến, ta đã xong rồi.']],
  qs:[{q:'What does B think happened?',o:['He missed his train','He was ill','He quit'],a:0,e:'“must have missed his train”.'},{q:'Why can’t he have forgotten?',o:['He set a reminder','He was told twice','He called'],a:0,e:'“set a reminder”.'}]},
 read:{text:'Experts predict that by 2040 electric vehicles will have replaced most petrol cars in many cities. By then, engineers will have developed batteries that charge in minutes, and governments will have built thousands of charging stations. Some analysts argue that this transition cannot have happened without strong policy support. Others say the change might have come faster if prices had fallen earlier. Whatever the case, most drivers will be using electric cars within two decades.',
  qs:[{q:'What will have happened by 2040?',o:['Electric vehicles will have replaced most petrol cars','Petrol cars will be cheaper','Cities will be empty'],a:0,e:'câu 2.'},{q:'What will engineers have developed?',o:['Faster planes','Batteries that charge in minutes','Free fuel'],a:1,e:'câu 3.'},{q:'What could have made the change faster?',o:['Earlier price falls','More petrol','Fewer roads'],a:0,e:'“if prices had fallen earlier”.'}]},
 speak:{shadow:['By this time next year, I will have finished my degree.','She must have been very tired; she fell asleep at once.'],prompt:'Dự đoán cuộc sống/nghề của bạn vào 5 năm nữa; suy đoán vì sao một người bạn vắng mặt.'},
 write:{prompt:'Write predictions about your city or job in 2035 (9 sentences). Use will be + V-ing, will have + V3, might/must have.',min:100,model:'By 2035, my city will have changed a lot. Public transport will have been extended, and many streets will be used only by pedestrians. By then, most companies will have introduced flexible working, so people will be working from home more often. Air quality might have improved because electric vehicles will have replaced many motorbikes. Of course, some things won’t have changed. The food will still be delicious, and the streets will be full of life.'}},

{id:'b2u5',lv:'B2',title:'Danh động từ, nguyên mẫu & modal quá khứ',goal:'Dùng đúng dạng động từ sau các động từ thường gặp.',
 vocab:[['consider','/kənˈsɪdɚ/','cân nhắc','I’m considering moving.'],['avoid','/əˈvɔɪd/','tránh','Avoid making mistakes.'],['attempt','/əˈtempt/','cố gắng','He attempted to leave.'],['refuse','/rɪˈfjuːz/','từ chối','She refused to answer.'],['postpone','/poʊˈspoʊn/','trì hoãn','We postponed the meeting.'],['manage','/ˈmænɪdʒ/','xoay xở làm được','I managed to finish.'],['insist on','/ɪnˈsɪst ɑːn/','khăng khăng','He insisted on paying.'],['look forward to','/lʊk ˈfɔːrwɚd tuː/','mong chờ','I look forward to meeting you.']],
 grammar:{body:'<ul><li><b>+ V-ing</b>: enjoy, avoid, consider, postpone, suggest, admit, mind, keep, risk · sau giới từ · look forward to <b>V-ing</b>, insist on <b>V-ing</b>.</li><li><b>+ to V</b>: decide, refuse, manage, attempt, afford, promise, hope, agree, plan.</li><li>Đổi nghĩa: <i>stop smoking</i> (bỏ hút) vs <i>stop to smoke</i> (dừng lại để hút); <i>remember to lock</i> (nhớ khóa) vs <i>remember locking</i> (nhớ là đã khóa); <i>try to</i> (cố gắng) vs <i>try -ing</i> (thử).</li><li><b>Modal quá khứ</b>: <i>should have + V3</i> (lẽ ra nên – đã không) · <i>needn’t have + V3</i> (đã làm mà không cần) · <i>could have + V3</i> (đã có thể).</li></ul>',
  quiz:[{q:'She avoided ___ the question.',o:['to answer','answering','answer'],a:1,e:'avoid + V-ing.'},{q:'He refused ___ the contract.',o:['signing','to sign','sign'],a:1,e:'refuse + to V.'},{q:'I look forward to ___ you next week.',o:['see','seeing','to see'],a:1,e:'look forward to + V-ing.'},{q:'You ___ have told me earlier! (đã không nói)',o:['should','must','can'],a:0,e:'should have + V3.'}]},
 listen:{dialog:[['A','Did you remember to send the invoice?','Bạn có nhớ gửi hóa đơn không?'],['B','Yes, I remember sending it yesterday afternoon.','Có, mình nhớ đã gửi chiều qua.'],['A','You needn’t have rushed; the deadline is next week.','Bạn không cần gấp đâu; hạn chót là tuần sau.'],['B','I know, but I wanted to avoid making a mistake later.','Mình biết, nhưng muốn tránh sai sót về sau.'],['A','Good thinking. I should have done the same.','Nghĩ hay đó. Lẽ ra mình cũng nên làm vậy.']],
  qs:[{q:'When did B send the invoice?',o:['This morning','Yesterday afternoon','Last week'],a:1,e:'“yesterday afternoon”.'},{q:'What does A say he should have done?',o:['The same thing','Called the client','Asked for help'],a:0,e:'“should have done the same”.'}]},
 read:{text:'Last year I decided to change careers. At first, I considered staying at my company, but I couldn’t stop thinking about starting my own business. I managed to save enough money and finally attempted to launch a small online shop. I didn’t expect it to be easy, and I was right. I should have prepared more carefully. I needn’t have spent so much on advertising. Still, I don’t regret trying. I look forward to expanding next year, and I’m planning to hire an assistant.',
  qs:[{q:'What did the writer decide to do?',o:['Stay at the company','Start an online shop','Retire'],a:1,e:'câu 2-3.'},{q:'What does the writer think about advertising?',o:['They spent too much on it','They didn’t use it','It was perfect'],a:0,e:'“needn’t have spent so much”.'},{q:'What is planned for next year?',o:['Closing the shop','Expanding and hiring','Changing careers again'],a:1,e:'câu cuối.'}]},
 speak:{shadow:['I’m looking forward to meeting you next week.','I should have called you earlier.'],prompt:'Nói về những việc bạn nên/không nên làm khác đi trong công việc năm ngoái.'},
 write:{prompt:'Write about plans and past mistakes at work or study (9 sentences). Use V-ing / to V and should have / needn’t have.',min:100,model:'This year I decided to improve my presentation skills. I avoid speaking in meetings because I’m afraid of making mistakes, but I’m determined to change. Last month I attempted to lead a project meeting, and it went better than I expected. I should have prepared more slides, but I managed to answer every question. I needn’t have worried so much. I’m looking forward to giving my next presentation, and I’m considering joining a public speaking club.'}},

{id:'b2u6',lv:'B2',title:'Viết trang trọng, hedging & liên kết ý học thuật',goal:'Viết đoạn văn/luận điểm mạch lạc, thận trọng, đúng văn phong học thuật.',
 vocab:[['furthermore','/ˌfɝːðɚˈmɔːr/','hơn nữa','Furthermore, it is cheaper.'],['nevertheless','/ˌnevɚðəˈles/','tuy nhiên vẫn','Nevertheless, we continued.'],['tend to','/tend tuː/','có xu hướng','People tend to save more.'],['appear','/əˈpɪr/','dường như','It appears to be true.'],['significant','/sɪɡˈnɪfɪkənt/','đáng kể','A significant increase.'],['in contrast','/ɪn ˈkɑːntræst/','ngược lại','In contrast, prices fell.'],['as a result','/æz ə rɪˈzʌlt/','do đó','As a result, sales rose.'],['on balance','/ɑːn ˈbæləns/','xét tổng thể','On balance, it was positive.']],
 grammar:{body:'<ul><li><b>Hedging</b> (thận trọng khi khẳng định): <i>It seems / appears that…, tends to, may/might/could, is likely to, to some extent, generally.</i> Thay vì “Cities cause stress” → “Living in cities <b>can</b> cause stress <b>for some people</b>.”</li><li><b>Từ nối học thuật</b>: thêm ý (furthermore, moreover, in addition) · tương phản (however, nevertheless, whereas, in contrast) · kết quả (consequently, as a result, therefore) · kết luận (in conclusion, on balance, to sum up).</li><li>Tránh: rút gọn (don’t → do not), từ quá thân mật, “I think” lặp lại.</li></ul>',
  quiz:[{q:'Which sentence is more formal and cautious?',o:['Social media ruins young people.','Social media may have a negative effect on some young people.','Everyone knows social media is bad.'],a:1,e:'Dùng may + giới hạn “some”.'},{q:'Costs rose. ___, the company raised prices.',o:['Consequently','Whereas','Although'],a:0,e:'Kết quả → Consequently.'},{q:'Urban areas are crowded; ___, rural areas are quiet.',o:['in contrast','as a result','moreover'],a:0,e:'Đối lập → in contrast.'},{q:'The trend ___ to continue.',o:['is likely','is liking','likely'],a:0,e:'is likely to + V.'}]},
 listen:{dialog:[['A','How should I write my conclusion?','Mình nên viết kết bài thế nào?'],['B','Summarise your main points. Start with “In conclusion” or “On balance”.','Tóm tắt ý chính. Bắt đầu bằng “In conclusion” hoặc “On balance”.'],['A','Should I add a new idea?','Có nên thêm ý mới không?'],['B','No. Avoid new ideas, and use cautious language, such as “it appears that”.','Không. Tránh ý mới, và dùng ngôn ngữ thận trọng như “it appears that”.'],['A','Got it. Thanks!','Hiểu rồi. Cảm ơn!']],
  qs:[{q:'How can a conclusion begin?',o:['In conclusion','By the way','Anyway'],a:0,e:'“In conclusion / On balance”.'},{q:'Should a conclusion contain new ideas?',o:['Yes','No'],a:1,e:'“Avoid new ideas”.'}]},
 read:{text:'Remote working has become increasingly common. On the one hand, it appears to increase productivity, as employees are less likely to be distracted by office noise. Furthermore, it may reduce commuting costs. On the other hand, some workers tend to feel isolated. In contrast, others report better work–life balance. Consequently, many companies are adopting hybrid models, whereby staff work partly at home. On balance, the evidence suggests that flexibility, rather than a single policy, is the best approach.',
  qs:[{q:'What is one benefit mentioned?',o:['Higher productivity','More noise','Longer hours'],a:0,e:'“appears to increase productivity”.'},{q:'What problem do some workers face?',o:['Isolation','Too many meetings','Low pay'],a:0,e:'“feel isolated”.'},{q:'What is the writer’s overall conclusion?',o:['Remote work is always best','Flexibility is the best approach','Offices should close'],a:1,e:'câu cuối.'}]},
 speak:{shadow:['On balance, the advantages seem to outweigh the disadvantages.','It appears that younger people tend to prefer flexible hours.'],prompt:'Trình bày quan điểm về làm việc từ xa trong 1 phút, dùng hedging và từ nối.'},
 write:{prompt:'Write a short formal essay: “Do the advantages of online learning outweigh the disadvantages?” (10 sentences, hedging + linking).',min:120,model:'Online learning has become increasingly popular, and it appears to offer several advantages. Firstly, it may be more flexible, as students can study at their own pace. Furthermore, it is likely to be cheaper than traditional courses. However, some learners tend to lose motivation without face-to-face contact. In contrast, classroom learning provides immediate feedback and social interaction. Consequently, many institutions now combine both methods. To some extent, the success of online learning depends on the learner’s discipline. On balance, the advantages seem to outweigh the disadvantages, provided that adequate support is offered.'}}
];

